mapper.select:
select 
from trade_prompt_binding


        and binding_name like concat('%', #{bindingName}, '%')


        and strategy_id = #{strategyId}


        and strategy_version_id = #{strategyVersionId}


        and symbol = #{symbol}


        and exchange_code = #{exchangeCode}


        and binding_scope = #{bindingScope}


        and template_code = #{templateCode}


        and enabled = #{enabled}


order by priority asc, id desc

